U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
# residual 20d momentum: trailing asset return minus rolling beta to cross-asset equal-weight return times market return
raw={}
for s in U:
 d=get_index_daily_data(s,days=3000)
 if d is not None and len(d): raw[s]=d[['date','close']].drop_duplicates('date').set_index('date').close
p=pd.DataFrame(raw).sort_index(); r=p.pct_change(); m=r.mean(axis=1)
vals={}; fwd={}
for s in U:
 x=pd.DataFrame({'r':r[s],'m':m}).dropna()
 beta=x.r.rolling(60,min_periods=40).cov(x.m)/x.m.rolling(60,min_periods=40).var()
 # use 20d residual cumulative return; beta is prior-day rolling available in construction
 res=r[s]-beta*m
 vals[s]=res.rolling(20,min_periods=15).sum()
 fwd[s]=p[s].shift(-1)/p[s]-1
F=pd.DataFrame(vals); R=pd.DataFrame(fwd)
ics=[]; ic5=[]; ic10=[]; turnovers=[]; nms=[]
for dt in F.index:
 a=F.loc[dt]; b=R.loc[dt]
 z=pd.concat([a,b],axis=1).dropna()
 if len(z)>=8: ics.append(z.iloc[:,0].corr(z.iloc[:,1])); nms.append(len(z))
 # forward non-overlapping-ish horizon return from t to t+h
 for h,out in [(5,ic5),(10,ic10)]:
  q=pd.concat([a,(p.shift(-h)/p-1).loc[dt]],axis=1).dropna()
  if len(q)>=8: out.append(q.iloc[:,0].corr(q.iloc[:,1]))
# rank turnover daily
rank=F.rank(axis=1,pct=True); turnovers=rank.diff().abs().mean(axis=1).dropna()
a=np.array(ics); print('dates',len(a),'avg_names',np.mean(nms),'coverage',np.mean(nms)/15,'IC',np.nanmean(a),'ICIR',np.nanmean(a)/np.nanstd(a,ddof=1),'hit',np.mean(a>0),'turnover',turnovers.mean(),'IC5',np.nanmean(ic5),'ICIR5',np.nanmean(ic5)/np.nanstd(ic5,ddof=1),'IC10',np.nanmean(ic10),'ICIR10',np.nanmean(ic10)/np.nanstd(ic10,ddof=1))
